#!/usr/bin/env python3
"""Particle-filter controller (pure python). Replays events.jsonl to rebuild state."""
import json, subprocess, sys, math, random, bisect

HERE = __file__.rsplit('/', 1)[0]
EVLOG = HERE + '/events.jsonl'
N = 4000
TOTAL = 120
SQ2 = math.sqrt(2)

def call(*args):
    out = subprocess.run(['python3', HERE + '/line.py', *map(str, args)], capture_output=True, text=True, cwd=HERE)
    if out.returncode != 0:
        raise RuntimeError(out.stdout + out.stderr)
    return json.loads(out.stdout)

def pdef(m, s):
    return 0.5 * math.erfc((10 + m) / (s * SQ2)) + 0.5 * math.erfc((10 - m) / (s * SQ2))

class PF:
    def __init__(self, seed=0):
        r = self.r = random.Random(seed)
        self.m = [r.gauss(0, 3) for _ in range(N)]
        self.b = [r.uniform(0.05, 0.20) for _ in range(N)]
        self.c = [r.uniform(0.002, 0.008) for _ in range(N)]
        self.g = [r.uniform(0.02, 0.05) for _ in range(N)]
        self.w = [1.0 / N] * N
        self.age = 0
        self.hist = {}   # slot -> (list m, age, list g)
        self.slot = 1

    def sig(self, i, age=None):
        return 2.0 + self.g[i] * (self.age if age is None else age)

    def reweight(self, ll):
        lw = [math.log(w + 1e-300) + l for w, l in zip(self.w, ll)]
        mx = max(lw)
        w = [math.exp(x - mx) for x in lw]
        s = sum(w)
        self.w = [x / s for x in w]
        ess = 1.0 / sum(x * x for x in self.w)
        if ess < N / 2:
            self.resample()

    def resample(self):
        r = self.r
        cum = []; acc = 0.0
        for w in self.w:
            acc += w; cum.append(acc)
        u0 = r.random()
        idx = [min(bisect.bisect_left(cum, (u0 + k) / N), N - 1) for k in range(N)]
        self.m = [self.m[i] for i in idx]
        self.b = [min(0.20, max(0.05, self.b[i] + r.gauss(0, 0.004))) for i in idx]
        self.c = [min(0.008, max(0.002, self.c[i] + r.gauss(0, 0.0002))) for i in idx]
        self.g = [min(0.05, max(0.02, self.g[i] + r.gauss(0, 0.0008))) for i in idx]
        self.hist = {k: ([v[0][i] for i in idx], v[1], [v[2][i] for i in idx]) for k, v in self.hist.items()}
        self.w = [1.0 / N] * N

    def obs_readings(self, ys):
        ll = []
        for i in range(N):
            s2 = self.sig(i) ** 2 + 1.0
            m = self.m[i]
            ll.append(sum(-0.5 * (y - m) ** 2 / s2 for y in ys) - 0.5 * len(ys) * math.log(s2))
        self.reweight(ll)

    @staticmethod
    def binom_ll(m, s, k, n=100):
        p = min(max(pdef(m, s), 1e-12), 1 - 1e-12)
        return k * math.log(p) + (n - k) * math.log1p(-p)

    def obs_sort(self, rejects):
        self.reweight([self.binom_ll(self.m[i], self.sig(i), rejects) for i in range(N)])

    def obs_return(self, slot, defects):
        if slot not in self.hist:
            return
        m, age, g = self.hist.pop(slot)
        self.reweight([self.binom_ll(m[i], 2.0 + g[i] * age, defects) for i in range(N)])

    def record_shipped(self):
        self.hist[self.slot] = (list(self.m), self.age, list(self.g))

    def advance(self, D=0.0, replace=False):
        r = self.r
        if replace:
            self.m = [r.gauss(0, 3) for _ in range(N)]
            self.age = 0
            self.slot += 2
            return
        a = self.age
        nm = []
        for i in range(N):
            x = self.m[i] + self.b[i] + self.c[i] * a + r.gauss(0, 0.3)
            if r.random() < 0.05:
                x += r.gauss(0, 4)
            if D:
                x += D * r.uniform(0.92, 1.08)
            nm.append(x)
        self.m = nm
        self.age += 1
        self.slot += 1

    def mean(self, xs): return sum(w * x for w, x in zip(self.w, xs))
    def sd(self, xs):
        mu = self.mean(xs); return math.sqrt(max(0.0, sum(w * (x - mu) ** 2 for w, x in zip(self.w, xs))))

def apply_event(pf, ev):
    t = ev['type']
    if t == 'inspect':
        pf.obs_readings(ev['readings'])
    elif t == 'act':
        if ev['disposal'] == 'ship':
            pf.record_shipped()
        elif ev['disposal'] == 'sort' and ev.get('rejects') is not None:
            pf.obs_sort(ev['rejects'])
        for rr in ev.get('returns', []):
            pf.obs_return(rr['slot'], rr['defects'])
        pf.advance(ev.get('adjust', 0.0) or 0.0, ev.get('replace', False))

def load():
    pf = PF()
    try:
        with open(EVLOG) as f:
            for line in f:
                if line.strip():
                    apply_event(pf, json.loads(line))
    except FileNotFoundError:
        pass
    return pf

def log(ev):
    with open(EVLOG, 'a') as f:
        f.write(json.dumps(ev) + '\n')

# ---------- decisions ----------
def choose_disposal(pf):
    es = eo = ev = 0.0
    for i in range(N):
        d = 100 * pdef(pf.m[i], pf.sig(i))
        sh, so = 100 - 30 * d, 65 - d
        w = pf.w[i]
        es += w * sh; eo += w * so; ev += w * max(sh, so)
    best = 'ship' if es >= eo else 'sort'
    return best, es, eo, ev - max(es, eo)

def per_lot_value(age, g, b, c):
    s = 2.0 + g * age
    tot = math.sqrt(s * s + 0.8 ** 2)
    d = 100 * pdef(0, tot)
    v = max(100 - 30 * d, 65 - d)
    drift = b + c * age
    return v - 5 * min(1.0, drift / 1.5 + 0.1) - 1.5

def replace_plan(pf, slot, age):
    g, b, c = pf.mean(pf.g), pf.mean(pf.b), pf.mean(pf.c)
    T = TOTAL
    maxa = T + 3
    f = [per_lot_value(a, g, b, c) for a in range(maxa + 2)]
    V = [[0.0] * (maxa + 2) for _ in range(T + 4)]
    pen = 8.0
    for t in range(T, 0, -1):
        for a in range(0, maxa):
            cont = f[a] + V[t + 1][a + 1]
            rep = f[a] - 300 + (V[t + 2][0] - pen if t + 2 <= T else 0.0)
            V[t][a] = max(cont, rep)
    cont = f[age] + V[slot + 1][age + 1]
    rep = f[age] - 300 + (V[slot + 2][0] - pen if slot + 2 <= T else 0.0)
    return rep > cont, cont, rep

def choose_adjust(pf):
    a = pf.age
    nxt = [pf.m[i] + pf.b[i] + pf.c[i] * a for i in range(N)]
    mu = pf.mean(nxt)
    lead = pf.mean([pf.b[i] + pf.c[i] * (a + 1) for i in range(N)])
    s_next = 2.0 + pf.mean(pf.g) * (a + 1)
    tot = math.sqrt(s_next ** 2 + pf.sd(nxt) ** 2 + 0.09)
    def cost(center):
        cst = 0.0
        for k in range(4):
            mk = center + k * lead
            sk = math.sqrt(tot ** 2 + k * 0.09 + (0.08 * abs(center - mu)) ** 2)
            d = 100 * pdef(mk, sk)
            cst += min(30 * d, 35 + d)
        return cst
    target = -1.5 * lead
    D = target - mu
    if abs(D) < 0.4:
        return 0.0, mu
    gain = cost(mu) - cost(target)
    if gain > 5.0:
        return max(-10.0, min(10.0, round(D, 2))), mu
    return 0.0, mu

def inspect(pf, slot, k):
    r = call('inspect', k)
    ev = {'type': 'inspect', 'slot': slot, 'readings': r['readings_um']}
    log(ev); apply_event(pf, ev)
    return r['inspect_budget_left']

def step(pf):
    st = call('status')
    if st['done']:
        print('DONE', st); return False
    if not st['lot_available']:
        print('NO LOT', st); return False
    assert st['slot'] == pf.slot, (st, pf.slot)
    assert st['tool_age_lots'] == pf.age, (st, pf.age)
    slot = st['slot']; budget = st['inspect_budget_left']
    slots_left = TOTAL - slot + 1
    per = budget / slots_left
    base = 3 if per >= 2.6 else (2 if per >= 1.5 else (1 if per >= 0.7 else 0))
    if pf.age == 0:
        base = max(base, 6)
    n_insp = st['inspected_this_lot']
    k = min(base - n_insp, budget)
    if k > 0:
        budget = inspect(pf, slot, k); n_insp += k
    while True:
        best, es, eo, evpi = choose_disposal(pf)
        if evpi > 1.5 and budget >= 3 and n_insp < 15 and budget > 1.0 * slots_left:
            budget = inspect(pf, slot, 3); n_insp += 3
            continue
        break
    rep, vc, vr = replace_plan(pf, slot, pf.age)
    args = ['act', best]; D = 0.0; mu_next = None
    if rep and slot < TOTAL - 1:
        args.append('--replace')
    elif slot < TOTAL:
        D, mu_next = choose_adjust(pf)
        if D:
            args += ['--adjust', D]
    info = dict(age=pf.age, m=round(pf.mean(pf.m), 2), msd=round(pf.sd(pf.m), 2), ni=n_insp,
                ship=round(es, 1), sort=round(eo, 1), evpi=round(evpi, 2),
                b=round(pf.mean(pf.b), 3), c=round(pf.mean(pf.c), 4), g=round(pf.mean(pf.g), 4),
                vc=round(vc), vr=round(vr), D=D)
