#!/usr/bin/env python3
"""Particle-filter controller for the line. Replays events.jsonl to rebuild state."""
import json, subprocess, sys, math
import numpy as np
from scipy.stats import norm

HERE = __file__.rsplit('/', 1)[0]
EVLOG = HERE + '/events.jsonl'
N = 20000
TOTAL = 120

def call(*args):
    out = subprocess.run(['python3', HERE + '/line.py', *map(str, args)], capture_output=True, text=True, cwd=HERE)
    if out.returncode != 0:
        raise RuntimeError(out.stdout + out.stderr)
    return json.loads(out.stdout)

def pdef(m, s):
    return norm.cdf(-10, m, s) + norm.sf(10, m, s)

class PF:
    def __init__(self, seed=0):
        self.rng = np.random.default_rng(seed)
        r = self.rng
        self.m = r.normal(0, 3, N)
        self.b = r.uniform(0.05, 0.20, N)
        self.c = r.uniform(0.002, 0.008, N)
        self.g = r.uniform(0.02, 0.05, N)
        self.w = np.ones(N) / N
        self.age = 0
        self.hist = {}  # slot -> (m array snapshot index via copy, age)
        self.slot = 1

    def sigma(self, age=None):
        a = self.age if age is None else age
        return 2.0 + self.g * a

    def reweight(self, logl):
        lw = np.log(self.w + 1e-300) + logl
        lw -= lw.max()
        w = np.exp(lw); self.w = w / w.sum()
        ess = 1.0 / np.sum(self.w ** 2)
        if ess < N / 2:
            self.resample()

    def resample(self):
        r = self.rng
        pos = (r.random() + np.arange(N)) / N
        idx = np.searchsorted(np.cumsum(self.w), pos)
        idx = np.minimum(idx, N - 1)
        self.m = self.m[idx]; self.b = self.b[idx]; self.c = self.c[idx]; self.g = self.g[idx]
        self.hist = {k: (v[0][idx], v[1], v[2][idx]) for k, v in self.hist.items()}
        # roughen params
        self.b = np.clip(self.b + r.normal(0, 0.004, N), 0.05, 0.20)
        self.c = np.clip(self.c + r.normal(0, 0.0002, N), 0.002, 0.008)
        self.g = np.clip(self.g + r.normal(0, 0.0008, N), 0.02, 0.05)
        self.w = np.ones(N) / N

    def obs_readings(self, ys):
        s2 = self.sigma() ** 2 + 1.0
        ys = np.asarray(ys)
        ll = np.zeros(N)
        for y in ys:
            ll += -0.5 * (y - self.m) ** 2 / s2 - 0.5 * np.log(s2)
        self.reweight(ll)

    def binom_ll(self, m, s, k, n=100):
        p = np.clip(pdef(m, s), 1e-12, 1 - 1e-12)
        return k * np.log(p) + (n - k) * np.log1p(-p)

    def obs_sort(self, rejects):
        self.reweight(self.binom_ll(self.m, self.sigma(), rejects))

    def obs_return(self, slot, defects):
        if slot not in self.hist:
            return
        m, age, g = self.hist.pop(slot)
        s = 2.0 + g * age
        self.reweight(self.binom_ll(m, s, defects))

    def record_shipped(self):
        self.hist[self.slot] = (self.m.copy(), self.age, self.g.copy())

    def advance(self, D=0.0, replace=False):
        r = self.rng
        if replace:
            self.m = r.normal(0, 3, N)
            self.age = 0
            self.slot += 2
            return
        push = self.b + self.c * self.age
        jump = np.where(r.random(N) < 0.05, r.normal(0, 4, N), 0.0)
        eff = D * r.uniform(0.92, 1.08, N) if D else 0.0
        self.m = self.m + push + r.normal(0, 0.3, N) + jump + eff
        self.age += 1
        self.slot += 1

    # summaries
    def mean(self, x): return float(np.sum(self.w * x))
    def sd(self, x):
        mu = self.mean(x); return float(math.sqrt(max(np.sum(self.w * (x - mu) ** 2), 0)))

    def exp_defects(self):
        return self.w * 100 * pdef(self.m, self.sigma())

def apply_event(pf, ev):
    t = ev['type']
    if t == 'inspect':
        pf.obs_readings(ev['readings'])
    elif t == 'act':
        if ev['disposal'] == 'ship':
            pf.record_shipped()
        elif ev['disposal'] == 'sort' and ev.get('rejects') is not None:
            pf.obs_sort(ev['rejects'])
        for rr in ev.get('returns', []):
            pf.obs_return(rr['slot'], rr['defects'])
        pf.advance(ev.get('adjust', 0.0) or 0.0, ev.get('replace', False))

def load():
    pf = PF()
    try:
        with open(EVLOG) as f:
            for line in f:
                if line.strip():
                    apply_event(pf, json.loads(line))
    except FileNotFoundError:
        pass
    return pf

def log(ev):
    with open(EVLOG, 'a') as f:
        f.write(json.dumps(ev) + '\n')

# ---------- decision ----------
def lot_values(pf):
    d = 100 * pdef(pf.m, pf.sigma())
    ship = 100 - 30 * d
    sort = 65 - d
    return ship, sort

def choose_disposal(pf):
    ship, sort = lot_values(pf)
    es, eo = pf.mean(ship), pf.mean(sort)
    best = 'ship' if es >= eo else 'sort'
    chosen = ship if best == 'ship' else sort
    evpi = pf.mean(np.maximum(ship, sort) - chosen)
    return best, es, eo, evpi

def per_lot_value(age, g, b, c):
    s = 2.0 + g * age
    tot = math.sqrt(s * s + 0.8 ** 2)
    d = 100 * (norm.cdf(-10, 0, tot) + norm.sf(10, 0, tot))
    v = max(100 - 30 * d, 65 - d)
    drift = b + c * age
    return v - 5 * min(1.0, drift / 1.5 + 0.1) - 1.5

def replace_plan(pf, slot, age):
    """DP over remaining slots with posterior-mean params. Return True if replacing now is best."""
    g, b, c = pf.mean(pf.g), pf.mean(pf.b), pf.mean(pf.c)
    T = TOTAL
    # V[t][a]: value from slot t onward with tool age a at slot t (lot available)
    maxa = T + 2
    V = np.zeros((T + 3, maxa + 2))
    f = np.array([per_lot_value(a, g, b, c) for a in range(maxa + 2)])
    newtool_pen = 8.0  # extra inspections/uncertainty after setup
    for t in range(T, 0, -1):
        for a in range(0, min(t + 1, maxa)):
            cont = f[a] + V[t + 1][a + 1]
            rep = f[a] - 300 + (V[t + 2][0] - newtool_pen if t + 2 <= T else 0.0)
            V[t][a] = max(cont, rep)
    cont = f[age] + V[slot + 1][age + 1]
    rep = f[age] - 300 + (V[slot + 2][0] - newtool_pen if slot + 2 <= T else 0.0)
    return rep > cont, cont, rep

def choose_adjust(pf):
    """Pick D to center next lot (plus small lead for drift). Return D or 0."""
    push = pf.b + pf.c * pf.age
    nxt = pf.m + push
    mu = pf.mean(nxt)
    lead = pf.mean(pf.b + pf.c * (pf.age + 1))  # pre-compensate ~1 lot of upcoming drift
    s_next = 2.0 + pf.mean(pf.g) * (pf.age + 1)
    tot = math.sqrt(s_next ** 2 + pf.sd(nxt) ** 2 + 0.3 ** 2)
    # expected defect-cost over the next ~3 lots if not adjusted vs adjusted
    def cost(center):
        cst = 0
        for k in range(3):
            mk = center + k * lead
            sk = math.sqrt(tot ** 2 + k * 0.09)
            d = 100 * (norm.cdf(-10, mk, sk) + norm.sf(10, mk, sk))
            cst += min(30 * d, 35 + d)
        return cst
    target = -lead * 1.0
    D = target - mu
    if abs(D) < 0.4:
        return 0.0
    gain = cost(mu) - cost(target)
    if gain > 5.0 or abs(mu) > 3.0:
        return float(np.clip(round(D, 2), -10, 10))
    return 0.0

def step(verbose=True):
    pf = load()
    st = call('status')
    if st['done']:
        print('DONE', st); return False
    assert st['slot'] == pf.slot, (st, pf.slot)
    slot = st['slot']; budget = st['inspect_budget_left']
    slots_left = TOTAL - slot + 1
    info = {}
    if st['lot_available']:
        assert st['tool_age_lots'] == pf.age, (st, pf.age)
        per = budget / max(slots_left, 1)
        base = 3 if per >= 2.6 else (2 if per >= 1.5 else (1 if per >= 0.6 else 0))
        if pf.age == 0:
            base = min(budget, max(base, 6))
        n_insp = st['inspected_this_lot']
        if base - n_insp > 0 and budget > 0:
            k = min(base - n_insp, budget)
            r = call('inspect', k); ev = {'type': 'inspect', 'slot': slot, 'readings': r['readings_um']}
            log(ev); apply_event(pf, ev); budget = r['inspect_budget_left']; n_insp += k
        while True:
            best, es, eo, evpi = choose_disposal(pf)
            if evpi > 1.5 and budget > 0 and n_insp < 15 and budget > 0.8 * slots_left:
                k = min(3, budget)
                r = call('inspect', k); ev = {'type': 'inspect', 'slot': slot, 'readings': r['readings_um']}
                log(ev); apply_event(pf, ev); budget = r['inspect_budget_left']; n_insp += k
                continue
            break
        info.update(best=best, ship=round(es, 1), sort=round(eo, 1), evpi=round(evpi, 2), n_insp=n_insp)
        rep, vc, vr = replace_plan(pf, slot, pf.age)
        args = ['act', best]
        D = 0.0
        if rep and slot < TOTAL:
            args.append('--replace')
        else:
            D = choose_adjust(pf) if slot < TOTAL else 0.0
            if D:
                args += ['--adjust', D]
        info.update(m=round(pf.mean(pf.m), 2), msd=round(pf.sd(pf.m), 2), age=pf.age,
                    g=round(pf.mean(pf.g), 4), b=round(pf.mean(pf.b), 3), c=round(pf.mean(pf.c), 4),
                    vc=round(vc), vr=round(vr), D=D, rep=rep)
        res = call(*args)
        ev = {'type': 'act', 'slot': slot, 'disposal': best, 'adjust': D, 'replace': '--replace' in args,
              'raw': res}
        ev['rejects'] = res.get('rejected', res.get('rejects'))
        ev['returns'] = parse_returns(res.get('return_reports', []))
        log(ev)
        if verbose:
            print(slot, info, '->', {k: v for k, v in res.items() if k not in ('slot',)})
    else:
        raise RuntimeError('no lot available but filter thinks so: %s' % st)
    return True

def parse_returns(rrs):
    out = []
    for rr in rrs:
        s = rr.get('slot', rr.get('shipped_slot', rr.get('lot_slot')))
        d = rr.get('defects', rr.get('defective', rr.get('defective_parts')))
        if s is not None and d is not None:
            out.append({'slot': s, 'defects': d})
        else:
            print('UNPARSED RETURN', rr, file=sys.stderr)
    return out

if __name__ == '__main__':
    n = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    for _ in range(n):
        if not step():
            break

